<?php
require_once __DIR__ . '/../../admin/implements/conexion.php';
require_once __DIR__ . '/funciones.php';
exigirAdmin();
if($_SERVER['REQUEST_METHOD']==='POST'){validarPost();$accion=$_POST['accion']??'';$id=(int)($_POST['id_libro']??0);if($accion==='eliminar'){$s=$pdo->prepare('SELECT COUNT(*) FROM prestamos WHERE id_libro=?');$s->execute([$id]);if((int)$s->fetchColumn()>0)mensaje('error','No se puede eliminar un libro con historial de préstamos.');else{$pdo->prepare('DELETE FROM libros WHERE id_libro=?')->execute([$id]);mensaje('ok','Libro eliminado.');}}else{$titulo=trim($_POST['titulo']??'');$autor=trim($_POST['autor']??'');$categoria=trim($_POST['categoria']??'');if($titulo===''||$autor===''||$categoria==='')mensaje('error','Completa todos los campos.');elseif($accion==='crear'){$pdo->prepare('INSERT INTO libros(titulo,autor,categoria) VALUES(?,?,?)')->execute([$titulo,$autor,$categoria]);mensaje('ok','Libro registrado.');}elseif($accion==='editar'&&$id){$pdo->prepare('UPDATE libros SET titulo=?,autor=?,categoria=? WHERE id_libro=?')->execute([$titulo,$autor,$categoria,$id]);mensaje('ok','Libro actualizado.');}}header('Location: listado.php');exit;}
$buscar=trim($_GET['buscar']??'');$estado=$_GET['estado']??'';$libros=buscarLibros($buscar,$estado);$editar=null;if(isset($_GET['editar'])){$s=$pdo->prepare('SELECT * FROM libros WHERE id_libro=?');$s->execute([(int)$_GET['editar']]);$editar=$s->fetch();}iniciarPagina('Libros');barraNavegacion('listado.php');
?>
<div class="encabezado-pagina"><div><span class="sobrelinea">CATÁLOGO</span><h1>Libros</h1><p>Registra, busca y actualiza la disponibilidad de los libros.</p></div></div><section class="panel mb-4"><h2><?= $editar?'Editar libro':'Registrar libro'; ?></h2><form method="post" class="row g-3"><input type="hidden" name="token_csrf" value="<?= escapar(tokenCsrf()); ?>"><input type="hidden" name="accion" value="<?= $editar?'editar':'crear'; ?>"><?php if($editar): ?><input type="hidden" name="id_libro" value="<?= (int)$editar['id_libro']; ?>"><?php endif; ?><div class="col-md-4"><label class="form-label">Título</label><input class="form-control" name="titulo" maxlength="200" required value="<?= escapar($editar['titulo']??''); ?>"></div><div class="col-md-4"><label class="form-label">Autor</label><input class="form-control" name="autor" maxlength="150" required value="<?= escapar($editar['autor']??''); ?>"></div><div class="col-md-3"><label class="form-label">Categoría</label><input class="form-control" name="categoria" maxlength="100" required value="<?= escapar($editar['categoria']??''); ?>"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary w-100">Guardar</button></div></form></section><section class="panel"><form method="get" class="row g-2 mb-3"><div class="col-md-6"><input class="form-control" name="buscar" placeholder="Buscar título, autor, categoría" value="<?= escapar($buscar); ?>"></div><div class="col-md-3"><select class="form-select" name="estado"><option value="">Todos los estados</option><option value="Disponible" <?= $estado==='Disponible'?'selected':''; ?>>Disponible</option><option value="Prestado" <?= $estado==='Prestado'?'selected':''; ?>>Prestado</option></select></div><div class="col-md-3"><button class="btn btn-outline-primary">Buscar</button> <a class="btn btn-outline-secondary" href="listado.php">Limpiar</a></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>ID</th><th>Título</th><th>Autor</th><th>Categoría</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($libros as $libro): ?><tr><td><?= (int)$libro['id_libro']; ?></td><td><?= escapar($libro['titulo']); ?></td><td><?= escapar($libro['autor']); ?></td><td><?= escapar($libro['categoria']); ?></td><td><span class="badge text-bg-<?= $libro['estado']==='Disponible'?'success':'primary'; ?>"><?= escapar($libro['estado']); ?></span></td><td class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="?editar=<?= (int)$libro['id_libro']; ?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar este libro?')"><input type="hidden" name="token_csrf" value="<?= escapar(tokenCsrf()); ?>"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id_libro" value="<?= (int)$libro['id_libro']; ?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form></td></tr><?php endforeach; ?><?php if(!$libros): ?><tr><td colspan="6" class="text-center">No hay libros.</td></tr><?php endif; ?></tbody></table></div></section><?php finPagina(); ?>
